                baseDelay = 10;
                break;
            case Channel.Push:
                baseDelay = 5;
                break;
            default:
                baseDelay = 15;
                break;
        }

        int delay = baseDelay * attempt;
        if (serverBusy && delay < 600)
            delay *= 2;
        if (delay > 3600)
            delay = 3600;
        else if (delay < 1)
